create table RB_LIMIT_SUM_INFO (CLIENT_NO VARCHAR(22) not null  ,LIMIT_SCENE_NO VARCHAR(50) not null  ,CHECK_OBJ_VAL VARCHAR(50) not null  ,LIMIT_SUM_AMT DECIMAL(38,2) null  ,LIMIT_SUM_CONTENT VARCHAR(500) null  ,LIMIT_SUM_NUM INT null  ,TRAN_CCY VARCHAR(3) null  ,REFERENCE VARCHAR(60) null  ,PRE_REFERENCE VARCHAR(60) null  ,TRAN_TIMESTAMP VARCHAR(26) null  ,EFFECT_DATE TIMESTAMP(3) null  ,EXPIRE_DATE TIMESTAMP(3) null  ,COMPANY VARCHAR(20) null  ,CREATE_TIMESTAMP VARCHAR(26) null  ,LAST_CHANGE_DATE TIMESTAMP(3) null  ,UPDATE_DATE TIMESTAMP(3) null  ,CREATE_DATE TIMESTAMP(3) null  , primary key(CLIENT_NO,LIMIT_SCENE_NO,CHECK_OBJ_VAL));